INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(371400, 0, 3714, 0, 0, 8, 'The Shattered Halls', 'The Shattered Halls lie at the heart of Hellfire Citadel, behind a door the fel orcs keep locked, and they belong to the Shattered Hand clan and its chieftain, Kargath Bladefist, who calls himself warchief of the Fel Horde. The halls are given over to war. Gladiators spar under the eyes of centurions, houndmasters keep rabid warhounds, assassins wait in the shadows, and in one long hall a blood guard drills archers to loose burning arrows down its length on his command. Shadowmoon acolytes and darkcasters serve beside the warriors, and everywhere the same cries ring out: the blood is our power, ours is the true Horde, for Kargath and for victory. Kargath''s lieutenants hold chambers of their own on the way to the warchief''s hall. Honor Hold and Thrallmar alike want Kargath dead.', 'zones/shattered_halls.txt (map 540: 3714, and 3535 Hellfire Citadel, the citadel-wide quest sort, not reachable); gameobject 184912 The Shattered Halls (door, lock 1804; the Shattered Halls Key 28395 from quests 10758/10764); DB spawns map 540: Shattered Hand Gladiator 17464, Centurion 17465, Houndmaster 17670 with Rabid Warhound 17669, Assassin 17695, Archer 17427, Blood Guard 17461, Flame Arrow 17687, Legionnaire 16700, Champion 17671, Heathen 17420, Reaver 16699; Shadowmoon Acolyte 16594, Darkcaster 17694; bosses 16807, 16809, 16808; creature_text 17465 groups 0 and 2 (Fight!; That''s enough. Now back off!), 17461 groups 0-3 (Archers, form ranks! On my mark! Ready! Aim! Fire!), shared yells group 1 (For Kargath! For Victory!; The blood is our power!; We are the true Horde!); quests 9492 and 9495 descriptions (Kargath''s self-styled title; both outposts want him defeated)'),
(371401, 2, 3714, 1, 0, 8, 'Grand Warlock Nethekurse', 'Grand Warlock Nethekurse, a fel orc warlock, holds a chamber in the Shattered Halls where he amuses himself by tormenting his own kind. Fel orc converts wait in his chamber, and he tries his spells on them, searing them, coiling death about them and cracking the ground beneath their feet, while they wail that their skin is on fire. Two strange braziers burn beside him, and the fel embers inside them lend his magic its power. When intruders arrive, he is happy to let them finish his work for him.', 'boss_nethekurse.cpp (Fel Orc Converts 17083 struck by Shadow Sear, Death Coil and Shadow Fissure for roleplay; he taunts as they are attacked and die); creature_text 17083 (It hurt!; Skin on fire!; Mommy!; No more!); creature_text 16807 groups 2-3; gameobject 181679 Fel Brazier (map 540); quest 9494 description (Nethekurse performs unrivaled magical feats augmented by the powers of a pair of strange braziers; fel embers); warcraft.wiki.gg/wiki/Grand_Warlock_Nethekurse (fel orc warlock; tortures young fel orcs)'),
(371402, 2, 3714, 2, 0, 8, 'Warbringer O''mrogg', 'Warbringer O''mrogg is a two-headed ogre who fights for the Fel Horde in the Shattered Halls, and his two heads agree on almost nothing. The left is always hungry, quick to grow bored, and given to offering foes their lives if they are nice to him. The right is sharper and sour, tired of doing all the hard work and of being fat because his twin is never full. They squabble over whom to kill next even in the middle of a fight, and still they swing hard enough to make the quarrel dangerous to anyone close by.', 'creature_text 19523 (left head: Me hungry!; If you nice me let you live; Me get bored; We kill someone else!) and 19524 (right head: Why don''t you let me do the talking?; You''re always hungry, that''s why we so fat!; That''s because I do all the hard work!; I''m tired. You kill next one!); boss_warbringer_omrogg.cpp (O''mrogg''s Left Head 19523 and Right Head 19524 speak for him; he switches targets); warcraft.wiki.gg/wiki/Warbringer_O''mrogg (two-headed ogre of the Fel Horde)'),
(371403, 2, 3714, 3, 0, 8, 'Warchief Kargath Bladefist', 'Kargath Bladefist, chieftain of the Shattered Hand, wears a blade where one hand should be, and he rules the Shattered Halls as warchief of the Fel Horde, a title no one granted him but himself. Long ago, while Ner''zhul worked to open the rifts that would tear Draenor apart, Kargath was left behind at Hellfire Citadel to hold off the Alliance. The fortress fell, and he escaped swearing he would one day take it back. He has. Now his army of crazed fel orcs means to see Thrallmar destroyed, and he proclaims his the true Horde and himself the only warchief. Thrall has ordered him defeated at all costs, and Danath Trollbane wants his weapon brought to Honor Hold.', 'quests 9492 (Danath, Alliance) and 9495 (Nazgrel, Horde) descriptions and reward text (self-styled Warchief; Thrall''s command; won''t rest until Thrallmar is destroyed; Warchief Kargath''s Fist); creature_text 16808; quest 11363 completion text (weapons in place of his hands); creature_template 16808 display 19799 (bladed left arm); warcraft.wiki.gg/wiki/Kargath_Bladefist (Beyond the Dark Portal, 2008: left at Hellfire Citadel with Dentarg to hold off the Alliance; vowed to reclaim it; became warchief of the Fel Horde); hellfire.json 348305 (self-styled warchief)'),
(371404, 3, 3714, 1, 0, 8, 'The Shattered Hand''s Key', 'At the Ata''mal Terrace in Shadowmoon Valley, Smith Gorlunk carried a freshly cast mold, meant for making a key of some sort. Whoever takes it from him finds an image engraved on its back that seems to belong to Hellfire Citadel, far away across Outland on the peninsula. That makes it worth showing to the commanders who face that fortress every day: Force Commander Danath Trollbane at Honor Hold, or Nazgrel, who leads the Horde''s forces at Thrallmar. What such a key might open, and whether it can be made at all, is for them to judge.', 'quests 10754 and 10755 descriptions (started by Primed Key Mold 31239/31241, dropped by Smith Gorlunk 22037, spawned at the Ata''mal Terrace, posarea 3757 in Shadowmoon Valley); quests 10762-10764 (Alliance) and 10756-10758 (Horde) descriptions and reward text; gameobject 184912 The Shattered Halls (lock 1804); hellfire.json 348331 notes (the key mold chain left unused for a Shattered Halls file)'),
(371405, 3, 3714, 2, 0, 8, 'Pride of the Fel Horde', 'Honor Hold and Thrallmar know precious little about the Fel Horde inside Hellfire Citadel, and what they know was bought with many lives. Kargath Bladefist''s troops are brutal and battle-hardened, fortified by foul magic. Their elite, the Shattered Hand legionnaires, centurions and champions, are feared by the rank and file and lead them as an officer corps. Field Commander Romus at Honor Hold and Shadow Hunter Ty''jin at Thrallmar agree on where any assault on the Fel Horde''s leadership must begin: with those officers, hunted down in the Shattered Halls. Whatever Overlord Hun Maimfist may say of them, Ty''jin warns, this Fel Horde is nothing to be trifled with.', 'quests 9493 (Romus 16830, Alliance) and 9496 (Ty''jin 16575, Horde) descriptions, completion and reward text; creature_template 16700, 17465, 17671 (the quests'' kill targets, spawned on map 540 only)'),
(371406, 3, 3714, 3, 0, 8, 'Kargath''s Prisoners', 'Kargath Bladefist keeps prisoners in the Shattered Halls, soldiers of Honor Hold or Thrallmar taken in the fighting, and he means to put them to death. A fellow captive met inside warns that the executions are near, and that an important officer is among the condemned: Captain Alina of the Alliance, or Captain Boneshatter of the Horde. Should intruders press too deep into his fortress, the warchief means to have the prisoners brought out and the executioner called, so that they pay for the trespass with their lives. In Shattrath, A''dal knows of them too, and would see the executioner''s axe come back without a drop of blood on its blade.', 'quests 9524 (Randy Whizzlesprocket 17288, Alliance) and 9525 (Drisella 17294, Horde) descriptions and reward text; quest 10884 description and reward text (A''dal); creature_text 16808 groups 3 and 4 (Bring out the Honor Hold / Thrallmar prisoners and call for the executioner! They''ll pay with their lives for this trespass!); instance_shattered_halls.cpp (on entering the hall, Kargath''s yell to the whole map; prisoners 17289/17290/17292, or for a Horde group 17295/17296/17297, are killed at 55, 65 and 80 minutes; prisoner givers 17288/17294 swap by team); shattrath.json 370320 part 6 (the trials named on DONE 10883)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(371401, 1, 0, 255, 'Nethekurse met the intruders with mockery, whether they cut down his converts one by one or tried to fight them all at once. Then he fought them himself, cleaving with shadow and splitting the ground beneath their feet, and when hard pressed he spun in a storm of darkness. It was not enough. He died with a sigh: what a shame.', 'creature_text 16807 groups 0 (You wish to fight us all at once?, if engaged before the converts are dead), 1-3 (converts handed over and mocked), 8 (What... a shame.); boss_nethekurse.cpp (Shadow Cleave, Shadow Fissure, Death Coil; Dark Spin at 25 percent health)'),
(371401, 2, 0, 255, 'One of his fel embers was carried out of the halls to Magus Zabraxis at Honor Hold. She has no hope of matching Nethekurse''s feats, she admits, and should not want to, but she would be a fool to ignore what the embers can do, and she means to study them in secret, for there are those who would forbid such research.', 'quest 9494 reward text (I can''t hope to replicate the feats of Grand Warlock Nethekurse, nor should I aspire to; fools to ignore the power of the fel embers; must keep my efforts secret)'),
(371402, 1, 0, 255, 'Even dying, the two heads could not agree. The left spent its last breath blaming its twin, insisting that this was all his fault. For once the right head had no answer ready, and the warbringer crashed to the floor of his chamber with the quarrel left unfinished.', 'creature_text 19523 group 8 (This all... your fault!); boss_warbringer_omrogg.cpp (JustDied: the left head speaks at once; the right head''s reply is scheduled 3.6 seconds later on O''mrogg''s own scheduler, which a dead creature no longer updates, so 19524 group 8 is never heard)'),
(371403, 1, 0, 255, 'Kargath met the intruders with a warrior''s boast, and fresh fighters kept pouring into the hall through a portal to fight beside him, while assassins rose from the shadows at its edges. It was not enough. The self-made warchief fell in his own hall, insisting with his last breath that the true Horde would prevail.', 'creature_text 16808 groups 0 (aggro: one of three boasts), 2 (The true Horde... will prevail.); boss_warchief_kargath_bladefist.cpp (four Shattered Hand Assassins summoned on engage; the Warchief''s Portal 17611 summons Heathen, Reaver and Sharpshooter guards during the fight)'),
(371403, 2, 0, 255, 'Nazgrel took the news of his death without triumph. In his prime, he said, Kargath had been a fine warrior, a hero and an example to his people, and his fall was a blow to all of them, above all to Thrall. Whatever happened to him at the end, the orcs should remember the one he once was, and the lessons of his downfall.', 'quest 9495 reward text'),
(371403, 3, 0, 255, 'Danath Trollbane took Kargath''s fist as proof that a major blow had been struck against the orcs. The Sons of Lothar once believed their blood had bought Honor Hold its safety; now, reinforced at last, they meant to do far more than defend it, and to keep the orcs on the defensive.', 'quest 9492 description (we Sons of Lothar believed we''d purchased Honor Hold''s safety with our blood) and reward text (major blow; keep the orcs on the defensive; now that we''ve been reinforced, far more than simply defend Honor Hold)'),
(371404, 1, 0, 255, 'Looking closer, the commander recognized the symbol on the key''s handle as the Shattered Hand''s own: there was a good chance the key would open the Shattered Halls. The mold went on to the outpost''s master smith, Dumphry at Honor Hold or Rohok at Thrallmar, for if anyone could forge such a key, he could.', 'quests 10762 and 10756 descriptions (offered on turning in 10754/10755: RewardNextQuest)'),
(371404, 2, 0, 255, 'Fel iron alone would serve in such a mold, and no forge of coal burned hot enough to temper it. The only fire fierce enough was the scalding fel fire at the heart of a Legion fel reaver, so the mold had to be plunged into the remains of one, brought down in Hellfire Peninsula by those bold enough to try.', 'quests 10763 and 10757 descriptions (only fel iron can be used with this mold); quests 10764 and 10758 descriptions (not enough heat; the insides of the Legion''s fel reavers; scalding core of fel fire)'),
(371404, 3, 0, 255, 'The charred mold gave up a working key, and the smith pronounced the work a success. All that was left was to carry it to Hellfire Citadel and try it on the locked door of the Shattered Halls, and there, Dumphry added, kill some orcs.', 'quests 10764 reward text (You''ve done it, laddie! Only thing left to do is for you to take it to Hellfire Citadel and kill yourself some orcs!) and 10758 reward text (You''ve succeeded! Only thing left for you to do is try it out.); quest_template RewardItem1 28395 Shattered Halls Key for both'),
(371405, 1, 0, 255, 'Romus was no fool about it. The fall of the legionnaires did not mean victory over the Fel Horde, he admitted, but it was a good first step, and with progress to report from the citadel, Honor Hold could perhaps begin to turn its attention to the Fel Horde elsewhere in the peninsula and across Outland.', 'quest 9493 completion text (I am not so naive as to think that the defeat of the Shattered Hand legionnaires heralds our victory, but is a good first step) and reward text (turn our attention to the Fel Horde presence in other parts of the peninsula and Outland)'),
(371405, 2, 0, 255, 'To Ty''jin, breaking the legionnaires meant the Fel Horde would be easier to face on the battlefield. He did not pretend the war had been won by it: even with its officers broken, the Fel Horde remained a formidable enemy, and Thrallmar would go on fighting it.', 'quest 9496 completion and reward text (with the legionnaires broken, it will be easier to face the Fel Horde on the battlefield, though they remain a formidable enemy)'),
(371406, 1, 0, 255, 'Captain Alina was saved before the executioner could reach her, and she admitted she had never expected a rescue party to come. She set about gathering the rest of the prisoners to lead them home to Honor Hold.', 'quest 9524 reward text'),
(371406, 2, 0, 255, 'Captain Boneshatter was saved before the executioner''s blow could fall, and he was glad of it, though not because he feared to die. When death comes for him, he swore, it will find him on the battlefield, covered in the blood of his enemies and taking them down with him.', 'quest 9525 reward text'),
(371406, 3, 0, 255, 'The executioner''s axe was carried to A''dal unused, not a drop of blood on its blade, and with it the proof that Kargath''s prisoners had been spared. The naaru declared the trial of mercy passed.', 'quest 10884 description (the unused axe of the executioner; it must not have a drop of blood on its blade) and reward text (you have passed the trial of mercy); instance_shattered_halls.cpp (the executioner 17301 carries the unused axe only while no prisoner has been killed)');
